begin;
select plan(12);
insert into auth.users(id,email) values ('00000000-0000-0000-0000-000000000038','competition38@example.com'),('00000000-0000-0000-0000-000000000138','outsider38@example.com');
insert into public.groups(id,name,invite_code,owner_id) values ('00000000-0000-0000-0000-000000003800','Model tests','PHASE388','00000000-0000-0000-0000-000000000038');
insert into public.group_members(group_id,user_id,role) values ('00000000-0000-0000-0000-000000003800','00000000-0000-0000-0000-000000000038','owner');
select lives_ok($$insert into competitions(id,group_id,creator_id,name,metric,starts_at,ends_at,timezone) values ('00000000-0000-0000-0000-000000003801','00000000-0000-0000-0000-000000003800','00000000-0000-0000-0000-000000000038','Spring DST','steps','2027-03-14 05:00Z','2027-03-15 04:00Z','America/New_York')$$,'a 23-hour DST calendar day is valid');
select is((select count(*)::int from competition_participants),0,'creation never auto-enrolls anyone');
select is((select include_manual from competitions limit 1),false,'manual entries are excluded by default');
select throws_ok($$update competitions set timezone='not/a-zone'$$,'P0001','invalid competition timezone','unknown timezones fail');
select throws_ok($$update competitions set ends_at='2027-03-15 03:00Z'$$,'P0001','competitions require 1 to 90 whole local calendar days','partial days fail');
select throws_ok($$update competitions set include_manual=true$$,'P0001','competition rules cannot be edited after creation','eligibility cannot change mid-competition');
select throws_ok($$update competitions set metric='weight'$$,'P0001','competition rules cannot be edited after creation','sensitive metrics are never enabled');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000038',true);
set local role authenticated;
select is((select count(*)::int from competitions),1,'group members read metadata');
select throws_ok($$delete from competitions$$,'42501',null,'clients cannot bypass server lifecycle functions');
select throws_ok($$update competition_rules set rules='{}'$$,'42501',null,'clients cannot rewrite scoring rules');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000138',true);
